import{_ as e,o as t,c as s,a3 as o}from"./chunks/framework.DdpBa4_E.js";const i="/ReadBooks/assets/image-050.Bf6wIOET.jpg",p="/ReadBooks/assets/image-015.BPdix2rk.jpg",h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/xialiu-shehui/66-感到幸福的时刻.md","filePath":"books/xialiu-shehui/66-感到幸福的时刻.md","lastUpdated":1794732511000}'),_={name:"books/xialiu-shehui/66-感到幸福的时刻.md"};function r(l,a,d,n,c,u){return t(),s("div",null,[...a[0]||(a[0]=[o('<h2 id="感到幸福的时刻" tabindex="-1">感到幸福的时刻 <a class="header-anchor" href="#感到幸福的时刻" aria-label="Permalink to &quot;感到幸福的时刻&quot;">​</a></h2><p>在被问及“你感到幸福的时刻”是什么时刻时，团块次代中阶层意识属于“上流”的男性大多选择享受美食的时候、全家在一起的时候以及与好友在一起的时候等；而“下流”人群则大多选择一个人独处的时候、轻松休憩的时候，选择让身体充分活动的人较少，由此可见不喜欢与别人接触正是这一人群的主要特征（见表6-5）。</p><p>再来看团块次代中上流阶层的女性，除了享受美食以外，学到新知识的时候、对社会有所贡献的时候以及自我得到展现的时候等，都能使她们感觉到幸福（见表6-6）。根据笔者的调查研究经验，这可以说是团块次代女性特有的倾向。</p><p>表6-5　不同阶层意识的团块次代男性感到幸福的时刻</p><p><img src="'+i+'" alt="" loading="lazy"></p><p>资料出处：Culture Studies研究所、e-FALCON共同实施的“欲求调查”</p><p>表6-6　不同阶层意识的团块次代女性感到幸福的时刻</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>资料出处：Culture Studies研究所、e-FALCON共同实施的“欲求调查”</p><p>可以看出，团块次代中阶层意识属于“下流”的女性与男性一样，选择一个人独处的时候感觉最幸福的也为数不少。</p>',10)])])}const f=e(_,[["render",r]]);export{h as __pageData,f as default};
